### Inherit root config in inline project definition

Source: https://github.com/vitest-dev/vitest/blob/main/docs/guide/migration/index.md

Inline projects in test.projects now automatically inherit plugins and root configuration without setting extends: true explicitly.

```ts
import { defineConfig } from 'vitest/config'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  test: {
    projects: [
      {
        // v4: this project didn't apply the react plugin
        // v5: the plugin is inherited from the root config
        test: {
          name: 'unit',
          include: ['**/*.unit.test.ts'],
        },
      },
    ],
  },
})
```

