### Test route components with props using createRoutesStub in React Router

Source: https://reactrouter.com/changelog

Sets up route components for unit testing using createRoutesStub to access loaderData directly via props instead of hooks.

```tsx
let RoutesStub = createRoutesStub([
  {
    path: "/",
    Component({ loaderData }) {
      let data = loaderData as { message: string };
      return <pre data-testid="data">Message: {data.message}</pre>;
    },
    loader() {
      return { message: "hello" };
    },
  },
]);

render(<RoutesStub />);

await waitFor(() => screen.findByText("Message: hello"));
```

